const kinds={new:'新项目',rebuild:'重构项目',derivative:'衍生项目'};
const grid=document.querySelector('#grid'),dialog=document.querySelector('#detail');
let filter='all';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repo=p=>'https://github.com/yukinsnow/'+encodeURIComponent(p.id);
const visual=p=>`<div class="visual ${esc(p.visual)}"><img src="${esc(p.image)}" alt="${esc(p.caption)}" loading="lazy"></div>`;
function render(){const q=document.querySelector('#search').value.trim().toLowerCase();const projects=PROJECTS.filter(p=>(filter==='all'||p.kind===filter)&&[p.name,p.en,p.description,...p.tags,p.category].join(' ').toLowerCase().includes(q));grid.innerHTML=projects.map(p=>`<article class="card"><button class="visual ${esc(p.visual)}" data-detail="${esc(p.id)}" aria-label="查看 ${esc(p.name)} 详情"><img src="${esc(p.image)}" alt="${esc(p.caption)}" loading="lazy"></button><p class="caption">${esc(p.caption)}</p><div class="card-body"><div class="card-top"><h3>${esc(p.name)}</h3><span class="badge ${p.kind}">${kinds[p.kind]}</span></div><p class="category">${esc(p.category)} / ${esc(p.en)}</p><p class="description">${esc(p.description)}</p><div class="tags">${p.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="card-bottom"><button class="detail-link" data-detail="${esc(p.id)}">了解项目 ↗</button><a class="source" href="${repo(p)}" target="_blank" rel="noopener">GitHub ↗</a></div></div></article>`).join('');document.querySelector('#empty').hidden=projects.length!==0;}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});
document.querySelector('#search').addEventListener('input',render);
grid.addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(!b)return;const p=PROJECTS.find(p=>p.id===b.dataset.detail);document.querySelector('#detail-body').innerHTML=visual(p)+`<a class="screenshot-full" href="${esc(p.image)}" target="_blank" rel="noopener">打开原图 ↗</a>`+`<p class="eyebrow">${esc(p.category)} / ${kinds[p.kind]}</p><h2>${esc(p.name)}</h2><h3>${esc(p.tagline)}</h3><p>${esc(p.description)}</p><ul>${p.features.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="note">${esc(p.note)}</p><a class="primary" href="${repo(p)}" target="_blank" rel="noopener">查看源码 ↗</a><a class="text-link" href="${repo(p)}/releases" target="_blank" rel="noopener">查看发布版本 ↗</a>${p.demo?`<a class="primary" href="${p.demo}" target="_blank" rel="noopener">在线体验 ↗</a>`:''}`;dialog.showModal()});
document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});render();

const total=String(PROJECTS.length).padStart(2,'0'); document.querySelector('.filters small').textContent=total; document.querySelector('.section-top .eyebrow').textContent='SELECTED PROJECTS / 01—'+total; document.querySelector('.art-index').textContent='01 — '+total+' / SELECTED WORKS';

